catalog_script_client.script:
function onLoad() {
    //Type appropriate comment here, and begin script below
    var urlParams = new URLSearchParams(top.window.location.search);

    var reqId = urlParams.get('reitem_id');
    if (reqId) {
        var ga = new GlideAjax('GetPreData');
        ga.addParam('sysparm_name', 'getPreviousRequestData');
        ga.addParam('sysparm_reqId', reqId);
        ga.getXMLAnswer(function(answer) {
            if (answer) {
                try {
                    var data = JSON.parse(answer);
                    if (data.request_for) {
                        g_form.setValue('request_for', data.request_for);
                    }
                    if (data.question1) {
                        g_form.setValue('question1', data.question1);
                    }
                    if (data.question2) {
                        g_form.setValue('question2', data.question2);
                    }
                } catch (e) {}
            }
        });
    }
}
